def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            min_r = min(x for x, y in cells)
            min_c = min(y for x, y in cells)
            shape = [(x - min_r, y - min_c) for x, y in cells]
            comps.append((min_c, min_r, color, shape))

    comps.sort(key=lambda item: item[0])
    out = [[0] * w for _ in range(h)]

    for i, (_, _, color, shape) in enumerate(comps):
        if i == 0:
            top, left = 0, 0
        elif i == 1:
            first_shape = comps[0][3]
            top = max(x for x, y in first_shape) + 1
            left = max(y for x, y in first_shape)
        else:
            top, left = i + max(x for x, y in comps[0][3]), i
        for dr, dc in shape:
            r, c = top + dr, left + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    return out
